CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_exchange.cession_bordereau_line
COMMENT 'The outbound cession bordereau, derived live from the canonical model: one line per policy premium movement ceded to a treaty, with the ceded amount computed from the contractual ceded share. This view - together with the data_dictionary - IS the bordereau: it is shared as a governed table, never exported to a spreadsheet. Grain: One row per ceded premium movement per policy per treaty.'
AS
SELECT
  tr.treaty_reference,
  DATE_TRUNC('MONTH', pt.transaction_date) AS reporting_month,
  p.policy_number,
  ins.name AS insured_name,
  p.line_of_business_code,
  p.inception_date,
  p.expiry_date,
  pt.currency_code,
  pt.amount AS gross_premium,
  ces.ceded_share,
  CAST(ROUND(pt.amount * ces.ceded_share, 2) AS DECIMAL(18,2)) AS ceded_premium
FROM lr_serverless_aws_us_catalog.bricksurance_reinsurance.cession ces
JOIN lr_serverless_aws_us_catalog.bricksurance_policy.policy p ON p.policy_id = ces.policy_id
JOIN lr_serverless_aws_us_catalog.bricksurance_reinsurance.treaty tr ON tr.treaty_id = ces.treaty_id
JOIN lr_serverless_aws_us_catalog.bricksurance_policy.premium_transaction pt ON pt.policy_id = p.policy_id
LEFT JOIN lr_serverless_aws_us_catalog.bricksurance_party.party_role pr
  ON pr.policy_id = p.policy_id AND pr.party_role_type_code = 'INSURED'
LEFT JOIN lr_serverless_aws_us_catalog.bricksurance_party.party ins ON ins.party_id = pr.party_id;
